+          </Text>
+          
+          {item.verseTelugu ? (
+            <Text style={styles.vcQuoteTel}>{stripHtml(item.verseTelugu)}</Text>
+          ) : null}
+
+          {item.videoTitle ? (
+            <Text style={styles.vcVideoTitle} numberOfLines={1}>🎬 {stripHtml(item.videoTitle)}</Text>
+          ) : null}
+
+          <View style={styles.vcBottom}>
